const MAX_FILES_CNI=2;const MAX_SIZE=2*1024*1024;function initCarrouselExemples(){const piste=document.querySelector('.carrousel-piste');if(!piste)return;const slides=piste.children.length;const points=document.querySelectorAll('.carrousel-points span');let index=0;setInterval(()=>{index=(index+1)%slides;piste.style.transform=`translateX(-${index * 100}%)`;points.forEach((p,i)=>p.classList.toggle('actif',i===index))},3500)}
document.addEventListener('DOMContentLoaded',initCarrouselExemples);function initZoneUpload(){const zone=document.querySelector('.zone-upload');const input=document.querySelector('#input-fichier');const liste=document.querySelector('.liste-fichiers');if(!zone||!input||!liste)return;zone.addEventListener('click',()=>input.click());input.addEventListener('change',(e)=>{const fichiers=Array.from(e.target.files);const fichiersExistants=liste.querySelectorAll('.fichier-item').length;if(fichiersExistants+fichiers.length>MAX_FILES_CNI){alert(`Vous ne pouvez pas ajouter plus de ${MAX_FILES_CNI} fichiers.`);input.value="";return}
fichiers.forEach(file=>{if(file.size>MAX_SIZE){alert(`${file.name} dépasse la limite de 2 Mo.`);return}
const item=document.createElement('div');item.className='fichier-item';const reader=new FileReader();reader.onload=(ev)=>{item.innerHTML=`
        <img class="miniature" src="${ev.target.result}" alt="">
        <span class="nom">${file.name} — ${(file.size / 1024 / 1024).toFixed(2)} Mo</span>
        <button class="supprimer" type="button" aria-label="Supprimer">✕</button>
      `;item.querySelector('.supprimer').addEventListener('click',()=>{item.remove()})};reader.readAsDataURL(file);liste.appendChild(item)});input.value=""})}
document.addEventListener('DOMContentLoaded',initZoneUpload);function allerEtape(numero){document.querySelectorAll('.ecran-etape').forEach(e=>e.classList.remove('actif'));const cible=document.querySelector(`#etape-${numero}`);if(cible)cible.classList.add('actif');document.querySelectorAll('.step').forEach(step=>{const n=parseInt(step.dataset.step,10);step.classList.remove('actif','fait');if(n<numero)step.classList.add('fait');if(n===numero)step.classList.add('actif');});window.scrollTo({top:0,behavior:'smooth'})}
function simulerVerificationServeur(callback){let tentative=0;const interval=setInterval(()=>{tentative++;console.log('Vérification du dossier… tentative',tentative);if(tentative>=3){clearInterval(interval);callback()}},600)}
function soumettreDossier(numeroDossierPrefix){const bouton=document.querySelector('#bouton-soumettre');if(bouton){bouton.disabled=!0;bouton.textContent='Envoi en cours…'}
simulerVerificationServeur(()=>{const numero=numeroDossierPrefix+'-'+Math.floor(100000+Math.random()*900000);const champNumero=document.querySelector('[data-numero-dossier]');if(champNumero)champNumero.textContent=numero;allerEtape(99)})}
